/* The field diary is a view of earned evidence, never a source of discoveries. */
const ExoDiary=(()=>{
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const button=(text,action,cls='')=>`<button class="diary-link ${cls}" onclick="${action}"${cls.includes('is-current')?' aria-current="page"':''}>${esc(text)}</button>`;
 const clue=e=>e?.kind==='log'&&typeof ExoFieldClues!=='undefined'?ExoFieldClues.get(e.structure,e.index):null;
 const read=e=>button(clue(e)?.object||e.title,`Exo.readRecord('${esc(e.id)}')`);
 const folio=(n,label)=>`<div class="diary-folio"><span>${esc(label)}</span><span>${String(n).padStart(2,'0')}</span></div>`;
 const page=(content,side='left',label='ECHO–9 / FIELD NOTES',n=1)=>`<section class="diary-page diary-${side}">${folio(n,label)}${content}<i class="diary-hole" aria-hidden="true"></i></section>`;
 function book(left,right,tab='places'){return `<article class="field-diary" aria-label="残页日记"><nav class="diary-bookmarks" aria-label="日记书签">${button('沿途',"Exo.journal('records')",tab==='places'?'is-current':'')}${button('夹页',"Exo.diaryConnections()",tab==='connections'?'is-current':'')}${button('合上日记','closeModal()','diary-close')}</nav><div class="diary-binding">${left}${right}</div><footer class="diary-footer"><span>EV–04 · 随身日记 / 破损处留白</span><span>观察会自动记下，随时可以继续走。</span></footer></article>`;}
 function frame(content){return `<div class="diary-desk">${content}</div>`;}
 const drawings={
  gauge:'M39 169H219V186H39Z M57 168V106M198 168V106 M78 55a35 35 0 1 0 1 0 M175 55a35 35 0 1 0 1 0 M78 91L94 69M175 91L190 67 M53 79l8 3m0-17l5 6m13-11v9m14-4l-5 7 M148 79l9 3m1-17l6 6m12-11v9m14-4l-5 7 M39 186l-10 19h200',
  valve:'M48 168V130H91V91H167V167H212V190H153V114H112V153H72V174 M130 71V112 M96 69a34 34 0 1 0 68 0a34 34 0 1 0 -68 0 M130 36V101 M97 69H163 M184 177l8 14m-11-10l-2 14',
  sample:'M60 60H90V77H86V165Q75 176 64 165V77H60Z M114 49H144V65H140V165Q128 176 118 165V65H114Z M168 63H198V79H194V165Q182 177 172 165V79H168Z M65 139l20-2m33 5l22-6m33 3h20 M46 180H211V192H46Z',
  cargo:'M45 75L173 47L222 83V171L90 204L45 166Z M45 75L90 112L222 83 M90 112V204 M76 69L123 105V194 M142 55L188 91V180 M105 130l48-13v33l-48 12Z M167 152l23-6',
  seat:'M83 41L176 38L182 121L89 128Z M89 128L192 122L214 162L107 177Z M107 177V208M201 164V197 M78 122V188 M101 47L120 116M155 44L141 119 M116 113l25-2v13l-25 2Z',
  seed:'M35 134L190 104L230 144L75 181Z M75 181V202L230 165V144 M35 134V157L75 202 M58 136l37 28m-7-35l38 28m-5-36l37 28m-5-35l37 28 M58 149L208 120 M80 139V94q-28-15-22-29q24-1 25 28q12-35 27-29q4 22-27 32 M119 132V97q-18-21-29-14q-1 17 29 20',
  radio:'M42 87L196 60L223 80V176L65 205L42 185Z M65 105L223 80M65 105V205 M82 121l55-10v54l-55 10Z M88 130l42-8m-42 19l42-8m-42 19l42-8 M179 142a17 17 0 1 0 1 0 M179 143l8 7 M94 76L79 22 M164 90l-2-49',
  relay:'M62 69L182 52L202 166L80 190Z M62 69L43 25L152 14L182 52 M90 167V106l19-5v28m16 33V97l17-3v29m15 33V92l18-3v30 M103 130l9 6m26-11l8 6m25-10l10 6 M90 106l-9-8m44-1l-7-8',
  projector:'M65 102L194 87L218 163L91 190Z M81 61a28 28 0 1 0 1 0 M159 43a35 35 0 1 0 1 0 M96 100L171 86 M194 119l35-8v27l-29 9 M230 111L250 91M230 139L249 157 M107 142l49-9m-42 19l41-10',
  map:'M48 61L211 44L225 183L60 207Z M60 207L40 177L28 51L48 61 M71 92L102 117L143 82L185 105L200 151 M71 97L99 123L148 113L177 165 M91 150L166 70M86 72L180 169 M66 174l31-2m69-5l35-6 M148 113a8 8 0 1 0 1 0',
  case:'M45 103L176 75L222 111L87 146Z M45 103V171L87 204L222 169V111 M87 146V204 M45 103L51 48L179 21L176 75 M130 136V155L151 151V131 M72 113l73-19l30 16l-73 21Z',
  bench:'M34 139L179 101L232 140L88 179Z M49 153V205M88 179V224M218 151V198 M112 94a26 26 0 1 0 1 0 M113 106a13 13 0 1 0 1 0 M137 109l26 12m-20-25l28 13 M58 139l39-21m-39 21l5 10l11-1',
  coil:'M78 75V184M190 64V168 M72 88a36 50 0 1 0 1 0 M185 68a36 50 0 1 0 1 0 M80 76L188 55M80 167L189 145 M104 68q-28 43 1 92m14-96q-28 43 1 92m14-96q-28 43 1 92m14-96q-28 43 1 92 M161 154q20 30 55 24 M60 199L205 174',
  weather:'M130 48V192M103 204L130 179L157 200 M69 107Q130 60 194 99Q135 150 69 107Z M69 107Q123 129 194 99 M87 76L176 126M100 129L168 69 M109 53L129 28L147 50 M129 28V17'
 };
 function sketch(kind,caption='现场速写'){const d=drawings[kind]||drawings.map;return `<figure class="diary-sketch"><svg viewBox="0 0 260 240" role="img" aria-label="${esc(caption)}的铅笔速写"><g fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><path d="${d}" stroke-width="1.6"/><path d="${d}" transform="translate(1.7,-1)" stroke-width=".55" opacity=".4"/><path d="M30 214l197-27M28 220l203-27M48 227l151-21M20 36l26-3M30 41l15-1" stroke-width=".8" opacity=".38"/></g></svg><figcaption>${esc(caption)} <span aria-hidden="true">↗</span></figcaption></figure>`;}
 function entryList(entries){return `<ol class="diary-entries">${entries.map(e=>`<li><small>${e.kind==='log'?'B'+(Math.floor(e.index/2)+1):'附页'}</small>${read(e)}<span aria-hidden="true">↗</span></li>`).join('')}</ol>`;}
 function index(cases,entries,threads,warning=''){
  const extra=entries.filter(e=>!e.structure&&e.kind!=='power'&&e.kind!=='depth'),latest=cases.find(c=>c.evidence.length),e=latest?.evidence[0],p=clue(e);
  const left=page(`<div class="diary-stamp">ECHO–9<br>EV–04 / PERSONAL</div><h1>残页日记</h1><p class="diary-subtitle">坠落之后，沿途所见。</p><p class="diary-hand">烧掉的页角已经找不回来了。<br>从还能看见的地方，接着记。</p><h2 class="diary-section">去过的地方</h2>${cases.length?`<ol class="diary-places">${cases.map((c,i)=>`<li>${button(c.name,`Exo.openSiteStory('${esc(c.id)}')`)}<span>${String(i+3).padStart(2,'0')}</span></li>`).join('')}</ol>`:'<p class="diary-blank">还没有写下地点。<br>靠近留下的物件，看看能不能打开、转动，或听到些什么。</p>'}`);
  const right=page(`${sketch(p?.kind||'case',p?.object||'随身物件 / 草图')}<div class="diary-tape" aria-hidden="true"></div><h2>${e?'记住这个细节':'先看，再记'}</h2><p>${e?esc(p?.observation||e.body):'一只没有回位的手轮、一格被取走的幼苗、货厢里多出来的座椅。它们不一定会说话，但都留下了痕迹。'}</p>${e?read(e):''}<p class="diary-margin">${threads.some(t=>t.findings.length)?'有些发现似乎连在一起。我把它们夹在后面，留着对照。':'还不知道的事，暂时留白。'}</p>${button('翻看夹页 →','Exo.diaryConnections()')}${extra.length?`<details class="diary-fold"><summary>旅途中的散页 · ${extra.length}</summary>${entryList(extra)}</details>`:''}${warning?`<p class="diary-save-warning" role="status">${esc(warning)}</p>`:''}`,'right','夹在封面后的纸',2);
  return book(left,right);
 }
 function lead(c){const l=c.crossLead;if(!l)return '<p class="diary-margin">没有答案的地方，先留一个问号。</p>';return `<aside class="diary-margin"><p>这件事还牵着另一处地方。</p><p>${esc(l.detail)}</p>${button(l.kind==='compare'?'翻到那一页':'在地图上找一找 ↗',l.kind==='compare'?`Exo.openSiteStory('${esc(l.siteId)}')`:`Exo.followEvidence('${esc(l.siteId)}',-1)`)}${l.sourceId?button('线索出自这件物品',`Exo.readRecord('${esc(l.sourceId)}')`):''}</aside>`;}
 function site(c){const e=c.evidence[0],p=clue(e);
  const left=page(`<small class="diary-overline">走到这里时</small><h1>${esc(c.name)}</h1><p class="diary-question">${esc(c.question)}</p>${c.evidence.length?entryList(c.evidence):'<p class="diary-blank">这一页还没写下发现。<br>先看看设备旁的磨痕、箱子和留下的东西。</p>'}${c.core?`<h2 class="diary-section">后来补上的一页</h2>${read(c.core)}`:''}${button('← 返回地点索引',"Exo.journal('records')")}`,'left','沿途 / 地点',3);
  const right=page(`${sketch(p?.kind||'map',p?.object||'留白 / 尚未观察')}<h2>${c.summaryEvidence?'把眼前的事记下来':'还没有答案'}</h2><p>${esc(c.summaryEvidence?c.summary:'先检查现场的物件。不必为了写满这一页而猜测。')}</p>${c.summaryEvidence?`<p class="diary-margin">${c.summaryConfidence==='hypothesis'?'这只是我的猜测，还要找别的东西核对。':'这是目前能确认的。更远的去向，还不能替他们写下。'}</p>${button('翻回这条发现',`Exo.readRecord('${esc(c.summaryEvidence)}')`)}`:''}${c.known?lead(c):''}<details class="diary-fold"><summary>需要找路时</summary><p>也可以先在房间里自己找。设备旁的物件能用 E 交互。</p>${c.nextLead?button('看看可以继续探索的位置',`Exo.followEvidence('${esc(c.nextLead.siteId)}',${c.nextLead.index})`):'<p>这里的线索已经记下了。</p>'}</details>`,'right','页角有烧损',4);
  return book(left,right);
 }
 function entry(e,c,related=[]){const p=clue(e),siblings=c?[...c.evidence,...(c.core?[c.core]:[])]:[],at=siblings.findIndex(x=>x.id===e.id),before=siblings[at-1],after=siblings[at+1];
  const left=page(`<small class="diary-overline">${esc(e.location||'旅途中')}</small><h1>${esc(p?.object||e.title)}</h1>${sketch(p?.kind||'case',p?.object||e.title)}<p class="diary-caption">${p?'手边的速写，比例未必准确。':'夹在这里，免得忘了。'}</p><p class="diary-source">${esc(e.source||e.location||'途中记下')}</p>${c?button('← '+c.name,`Exo.openSiteStory('${esc(c.id)}')`):button('← 返回日记',"Exo.journal('records')")}`,'left','亲手检查过的物件',e.index===undefined?5:e.index*2+5);
  const right=page(`<h2>${p?'我注意到的':'写在这一页'}</h2><p class="diary-observation">${esc(p?ExoFieldClues.note(e.structure,e.index,e.body):e.body)}</p>${e.meaning&&e.meaning!==e.body?`<div class="diary-thought"><span>${e.confidence==='hypothesis'?'还不能确定':'在页边补一句'}</span><p>${esc(e.meaning)}</p></div>`:''}${p?`<details class="diary-fold"><summary>夹在旁边的原件摘抄</summary><small>${esc(e.source)}</small><p>${esc(e.body)}</p></details>`:''}${related.length?`<details class="diary-fold"><summary>让我想到另一处发现</summary>${entryList(related)}</details>`:''}${c?.crossLead?.sourceId===e.id?lead(c):''}<nav class="diary-page-turns" aria-label="翻页">${before?button('← 上一页',`Exo.readRecord('${esc(before.id)}')`):''}${after?button('下一页 →',`Exo.readRecord('${esc(after.id)}')`):''}</nav>`,'right',e.confidence==='hypothesis'?'疑问保留':'随手记下',e.index===undefined?6:e.index*2+6);
  return book(left,right);
 }
 function connections(threads){const found=threads.filter(t=>t.findings.length),columns=[[],[]];found.forEach((t,i)=>columns[i%2].push(`<section class="diary-connection"><h2>${esc(t.title)}</h2>${t.primary.map(e=>`<p>${esc(e.meaning)}</p><small class="diary-citation">${e.confidence==='hypothesis'?'尚待核实 · ':''}${esc(e.location||'沿途')} ${read(e)}</small>`).join('')}${t.additional.length?`<details class="diary-fold"><summary>另外几页也提到过</summary>${entryList(t.additional)}</details>`:''}</section>`));return book(page(`<h1>散落的线头</h1><p class="diary-hand">把已经看见的放在一起。<br>连不上的地方，先别接上。</p>${columns[0].join('')||'<p class="diary-blank">还没有可以对照的发现。</p>'}`,'left','夹页 / 彼此呼应'),page(`${columns[1].join('')||sketch('map','未完成的路线')}<p class="diary-margin">空白仍是空白。灯亮着，不代表道路已安全；听见回应，也还不知道是谁。</p>`,'right','仍有缺页',2),'connections');}
 return {frame,index,site,entry,connections,sketch};
})();
if(typeof module!=='undefined')module.exports=ExoDiary;
